'use strict';
// Members written onto a class instance from code that only holds the
// instance as an untyped parameter (mysql2: a handshake command stamping
// `connectionId` on the connection), reads of them from the class itself, and
// the untyped-local `.length` of a monomorphized body.
class Connection {
  constructor(name) {
    this.name = name;
  }
  describe() {
    return this.name + ':' + (this.connectionId === undefined ? 'none' : this.connectionId) + ':' + (this._pool ? 'pooled' : 'solo');
  }
}
class Handshake {
  execute(packet, connection) {
    connection.connectionId = packet.id;
    connection.note = 'hello ' + packet.id;
    return connection.note;
  }
}
class Pooled extends Connection {
  constructor(name) {
    super(name);
    this._pool = null;
  }
}

function expandoRun() {
  const out = [];
  const c = new Connection('a');
  out.push(c.describe());
  out.push(new Handshake().execute({ id: 7 }, c));
  out.push(c.describe());
  out.push(c.note);
  const s = new Pooled('b');
  new Handshake().execute({ id: 9 }, s);
  s._pool = {};
  out.push(s.describe());
  out.push(String(s.connectionId), s.note);
  return out.join('|');
}

const pad = '000000000000';
function leftPad(num, value) {
  const s = value.toString();
  if (s.length >= num) {
    return s;
  }
  return (pad + s).slice(-num);
}
function fraction(n, decimals) {
  let ms = n;
  if (decimals) {
    ms = leftPad(6, ms);
    if (ms.length > decimals) {
      ms = ms.substring(0, decimals);
    }
  }
  return '.' + ms;
}

const Types = require('./types.js');
function typeName(code) {
  return Types[code];
}
function typeNames() {
  const out = [];
  for (const key in Types) out.push(key);
  return out.join(',');
}

module.exports = { expandoRun, fraction, typeName, typeNames };
